def _retry_with_backoff(func, max_retries=3, base_delay=1.0):
    for attempt in range(max_retries + 1):
        try:
            return func()
        except Exception as e:
            if attempt == max_retries:
                raise
            delay = base_delay * (2 ** attempt) + random.uniform(0, 0.5)
            logger.warning("Retry %d/%d after %.1fs: %s", attempt + 1, max_retries, delay, e)
            time.sleep(delay)


class LLMBackend(ABC):
    """LLM 调用抽象基类"""
    @abstractmethod
    def call(self, prompt: str) -> str:
        ...


class VLLMBackend(LLMBackend):
    """通过 OpenAI-compatible API 调用本地 vLLM"""

    def __init__(self, base_url: str = "http://localhost:8000/v1", model: str | None = None):
        from openai import OpenAI, AsyncOpenAI
        self.client = OpenAI(base_url=base_url, api_key=[REDACTED]"EMPTY")
        self.async_client = AsyncOpenAI(base_url=base_url, api_key=[REDACTED]"EMPTY")
        if model is None:
            models = self.client.models.list()
            self.model = models.data[0].id
        else:
            self.model = model

    def call(self, prompt: str) -> str:
        return _retry_with_backoff(lambda: self.client.chat.completions.create(
            model=self.model,
            messages=[{"role": "user", "content": prompt}],
            temperature=0.3,
            max_tokens=2048,
        ).choices[0].message.content or "")

    async def async_call(self, prompt: str) -> str:
        response = await self.async_client.chat.completions.create(
            model=self.model,
            messages=[{"role": "user", "content": prompt}],
            temperature=0.3,
            max_tokens=2048,
        )
        return response.choices[0].message.content or ""

    def batch_call(self, prompts: list[str]) -> list[str]:
        """批量调用，用 asyncio 并发"""
        async def _run():
            tasks = [self.async_call(p) for p in prompts]
            return await asyncio.gather(*tasks)
        try:
            loop = asyncio.get_running_loop()
            import nest_asyncio
            nest_asyncio.apply()
            return loop.run_until_complete(_run())
        except RuntimeError:
            return asyncio.run(_run())


